<button id="sc-back-top" title="Back to top" onclick="window.scrollTo({top:0,behavior:'smooth'})">
  <i class="fas fa-chevron-up"></i>
</button>

<script>
document.addEventListener('DOMContentLoaded', function () {
  var cards     = Array.from(document.querySelectorAll('.calendar-card'));
  var countEl   = document.getElementById('scCount');
  var searchEl  = document.getElementById('scSearch');
  var noResults = document.getElementById('scNoResults');
  var sugBox    = document.getElementById('scSuggestions');

  /* ââ Tags ââââââââââââââââââââââââââââââââââââââââââââââââââââââ
   * Reads the card title and auto-detects the programme level tag.
   * Checked in priority order (PG Diploma before PG, etc.).
   *
   * TO ADD A NEW ABBREVIATION â find the right line and append:
   *   PG Diploma : "postgraduate diploma|pg diploma"
   *   PhD        : "\bph\.?d\b|doctor of"
   *   PG         : "\bmaster\b|m\.sc.|m\.a.|m\.com.|mba\b|m\.c\.a.|mca\b|m\.ed.|m\.s\.w.|m\.des."
   *   UG         : "\bbachelor\b|b\.sc.|b\.a.|b\.com.|bba\b|b\.b\.a.|bca\b|b\.c\.a.|b\.ed.|b\.s\.w.|b\.voc."
   *   Shift III  : added on top of the level tag if title contains "Shift III"
   *
   * Examples:
   *   "Master of Science (M.Sc.) in Physics"              â' PG
   *   "Bachelor of Commerce (B.Com.)"                     â' UG
   *   "Postgraduate Diploma in Cyber Security"            â' PG Diploma
   *   "Bachelor of Business Administration (BBA) Shift III" â' UG + Shift III
   *   "Ph.D in Chemistry"                                 â' PhD
   * âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ */
  function getTags(title) {
    var tags = [];
    // PG Diploma â checked first so it doesn't match PG by mistake
    if (/postgraduate diploma|pg diploma/i.test(title))
      tags.push({ label: 'PG Diploma', cls: 'sc-tag-pgdip' });
    // PhD
    else if (/\bph\.?d\b|doctor of/i.test(title))
      tags.push({ label: 'PhD', cls: 'sc-tag-phd' });
    // PG â add new master's abbreviations after m\.s\.w\.
    else if (/\bmaster\b|m\.sc\.|m\.a\.|m\.com\.|mba\b|m\.c\.a\.|mca\b|m\.ed\.|m\.s\.w\./i.test(title))
      tags.push({ label: 'PG', cls: 'sc-tag-pg' });
    // UG â add new bachelor's abbreviations after b\.s\.w\.
    else if (/\bbachelor\b|b\.sc\.|b\.a\.|b\.com\.|bba\b|b\.b\.a\.|bca\b|b\.c\.a\.|b\.ed\.|b\.s\.w\./i.test(title))
      tags.push({ label: 'UG', cls: 'sc-tag-ug' });
    // Shift III â added on top of the level tag above
    if (/shift\s*iii/i.test(title))
      tags.push({ label: 'Shift III', cls: 'sc-tag-shift' });
    return tags;
  }
  cards.forEach(function (card) {
    var titleEl = card.querySelector('.calendar-title, h5');
    if (!titleEl) return;
    var tags = getTags(titleEl.textContent);
    if (!tags.length) return;
    var wrap = document.createElement('div');
    wrap.className = 'sc-tags';
    tags.forEach(function (t) {
      var s = document.createElement('span');
      s.className = 'sc-tag ' + t.cls;
      s.textContent = t.label;
      wrap.appendChild(s);
    });
    titleEl.insertAdjacentElement('afterend', wrap);
  });

  /* ââ Count badges on filter tabs ââ */
  var levelMap = { ug: 0, pg: 0, pgdip: 0, phd: 0 };
  cards.forEach(function (card) {
    var titleEl = card.querySelector('.calendar-title, h5');
    if (!titleEl) return;
    var t = titleEl.textContent;
    if (/postgraduate diploma|pg diploma/i.test(t)) levelMap.pgdip++;
    else if (/\bph\.?d\b|doctor of/i.test(t)) levelMap.phd++;
    else if (/\bmaster\b|m\.sc\.|m\.a\.|m\.com\.|mba\b|m\.c\.a\.|mca\b|m\.ed\.|m\.s\.w\./i.test(t)) levelMap.pg++;
    else if (/\bbachelor\b|b\.sc\.|b\.a\.|b\.com\.|bba\b|b\.b\.a\.|bca\b|b\.c\.a\.|b\.ed\.|b\.s\.w\./i.test(t)) levelMap.ug++;
    card.setAttribute('data-level',
      /postgraduate diploma|pg diploma/i.test(t) ? 'pgdip' :
      /\bph\.?d\b|doctor of/i.test(t) ? 'phd' :
      /\bmaster\b|m\.sc\.|m\.a\.|m\.com\.|mba\b|m\.c\.a\.|mca\b|m\.ed\.|m\.s\.w\./i.test(t) ? 'pg' :
      /\bbachelor\b|b\.sc\.|b\.a\.|b\.com\.|bba\b|b\.b\.a\.|bca\b|b\.c\.a\.|b\.ed\.|b\.s\.w\./i.test(t) ? 'ug' : 'other');
  });
  var fcAll = document.getElementById('fc-all'); if (fcAll) fcAll.textContent = cards.length;
  ['ug','pg','pgdip','phd'].forEach(function (k) {
    var el = document.getElementById('fc-' + k); if (el) el.textContent = levelMap[k];
  });

  /* ââ Count ââ */
  if (countEl) countEl.textContent = cards.length + ' document' + (cards.length === 1 ? '' : 's') + ' listed';
  if (!searchEl) return;


  /* ââ Cache card text ââ */
  var cardTexts   = cards.map(function (c) { return c.textContent.toLowerCase(); });
  var filterCache = {};

  /* ââ Fuzzy match ââ */
  function isSubseq(n, h) {
    var ni = 0;
    for (var hi = 0; hi < h.length && ni < n.length; hi++)
      if (n[ni] === h[hi]) ni++;
    return ni === n.length;
  }
  function fuzzyMatch(text, q) {
    if (!q) return true;
    if (text.includes(q)) return true;
    return q.split(/\s+/).filter(Boolean).every(function (qw) {
      if (text.includes(qw)) return true;
      if (qw.length < 4) return false;
      return text.split(/\W+/).some(function (tw) {
        return tw.length >= qw.length && tw.length <= qw.length + 3 && isSubseq(qw, tw);
      });
    });
  }

  /* ââ Filter cards ââ */
  function runFilter(q) {
    var ql = q.toLowerCase().trim();
    var res = filterCache[ql];
    if (!res) { res = cardTexts.map(function (t) { return fuzzyMatch(t, ql); }); filterCache[ql] = res; }
    var vis = 0;
    cards.forEach(function (card, i) {
      if (res[i]) { card.style.removeProperty('display'); vis++; }
      else card.style.setProperty('display', 'none', 'important');
    });
    if (countEl) countEl.textContent = vis + ' document' + (vis === 1 ? '' : 's') + (ql ? ' found' : ' listed');
    if (noResults) noResults.style.display = vis === 0 ? '' : 'none';
  }

  /* ââ Suggestion bank ââ */
  var seen = {}, bank = [];
  function addSug(label, type) {
    var k = label.toLowerCase().replace(/\s+/g, ' ').trim();
    if (!seen[k] && k.length > 1) { seen[k] = 1; bank.push({ label: label.replace(/\s+/g, ' ').trim(), type: type }); }
  }
  ['January','February','March','April','May','June','July','August','September','October','November','December']
    .forEach(function (m) { addSug(m, 'date'); });
  for (var y = 2024; y <= 2030; y++) addSug(String(y), 'date');
  cards.forEach(function (card) {
    var titleEl = card.querySelector('.calendar-title, h5');
    if (!titleEl) return;
    var txt = titleEl.textContent.trim();
    var d1 = txt.match(/\b(\d{1,2}(?:st|nd|rd|th)\s+[A-Z][a-z]+\s+\d{4})\b/i);
    if (d1) addSug(d1[1], 'date');
    var d2 = txt.match(/\b([A-Z][a-z]+\s+\d{4})\b/);
    if (d2) addSug(d2[1], 'date');
    var prog = txt.replace(/provisional list.*?for\s*/i, '').replace(/\s*[-â]?\s*interview.*$/i, '').trim();
    if (prog.length > 3) addSug(prog, 'programme');
  });

  /* ââ Highlight ââ */
  function esc(s) { return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function highlight(label, q) {
    var idx = label.toLowerCase().indexOf(q.toLowerCase());
    if (idx >= 0)
      return esc(label.slice(0, idx)) + '<strong class="sc-sug-match">' + esc(label.slice(idx, idx + q.length)) + '</strong>' + esc(label.slice(idx + q.length));
    return esc(label);
  }

  /* ââ Dropdown ââ */
  var activeIdx = -1;
  function showSug(q) {
    if (!q) { hideSug(); return; }
    var hits = bank.filter(function (s) { return fuzzyMatch(s.label.toLowerCase(), q.toLowerCase()); }).slice(0, 8);
    if (!hits.length) { hideSug(); return; }
    activeIdx = -1;
    var icons = { date: 'fa-calendar-alt', programme: 'fa-graduation-cap' };
    sugBox.innerHTML = hits.map(function (s, i) {
      return '<div class="sc-sug-item" data-val="' + esc(s.label) + '" data-idx="' + i + '">' +
        '<span class="sc-sug-left">' +
          '<i class="fas ' + (icons[s.type] || 'fa-search') + ' sc-sug-icon"></i>' +
          '<span class="sc-sug-text">' + highlight(s.label, q) + '</span>' +
        '</span>' +
        '<span class="sc-sug-type">' + s.type + '</span>' +
        '</div>';
    }).join('');
    sugBox.classList.add('show');
  }
  function hideSug() { sugBox.classList.remove('show'); activeIdx = -1; }
  function pickSug(val) { searchEl.value = val; hideSug(); applyFilters(); if (clearBtn) clearBtn.style.display = 'block'; searchEl.focus(); }

  var clearBtn = document.getElementById('sc-clear-btn');
  searchEl.addEventListener('input', function () {
    applyFilters();
    showSug(this.value.trim());
    if (clearBtn) clearBtn.style.display = this.value ? 'block' : 'none';
  });
  searchEl.addEventListener('keydown', function (e) {
    var items = sugBox.querySelectorAll('.sc-sug-item');
    if (!items.length) return;
    if (e.key === 'ArrowDown')    { e.preventDefault(); activeIdx = Math.min(activeIdx + 1, items.length - 1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); activeIdx = Math.max(activeIdx - 1, 0); }
    else if (e.key === 'Enter' && activeIdx >= 0) { e.preventDefault(); pickSug(items[activeIdx].getAttribute('data-val')); return; }
    else if (e.key === 'Escape')  { hideSug(); return; }
    items.forEach(function (el, i) { el.classList.toggle('sc-sug-active', i === activeIdx); });
  });

  /* works on desktop (mousedown) and mobile (touchstart) */
  function onPick(e) {
    var item = e.target.closest('.sc-sug-item');
    if (!item) return;
    e.preventDefault();
    pickSug(item.getAttribute('data-val'));
  }
  sugBox.addEventListener('mousedown',  onPick);
  sugBox.addEventListener('touchstart', onPick, { passive: false });

  document.addEventListener('click', function (e) {
    if (!searchEl.contains(e.target) && !sugBox.contains(e.target)) hideSug();
  });

  /* ââ Active filter state ââ */
  var activeFilter = 'all';

  /* ââ applyFilters: combine search text + active level filter ââ */
  function applyFilters() {
    var q = searchEl.value.toLowerCase().trim();
    var vis = 0;
    var suggestSet = {};
    cards.forEach(function (card, i) {
      var textMatch = !q || fuzzyMatch(cardTexts[i], q);
      var levelMatch = activeFilter === 'all' || card.getAttribute('data-level') === activeFilter;
      if (textMatch && levelMatch) {
        card.style.removeProperty('display');
        vis++;
      } else {
        card.style.setProperty('display', 'none', 'important');
        if (!textMatch && levelMatch) {
          var titleEl2 = card.querySelector('.calendar-title, h5');
          if (titleEl2) {
            var prog2 = titleEl2.textContent.replace(/provisional list.*?for\s*/i,'').replace(/\s*[-â]?\s*interview.*$/i,'').trim();
            if (prog2.length > 3) suggestSet[prog2] = 1;
          }
        }
      }
    });
    if (countEl) countEl.textContent = vis + ' document' + (vis === 1 ? '' : 's') + (q ? ' found' : ' listed');
    if (noResults) {
      noResults.style.display = vis === 0 ? '' : 'none';
      if (vis === 0) {
        var sl = document.getElementById('sc-suggest-list');
        if (sl) {
          var pills = Object.keys(suggestSet).slice(0, 6);
          sl.innerHTML = pills.length
            ? pills.map(function (p) {
                return '<button class="sc-suggest-pill" onclick="document.getElementById(\'scSearch\').value=\'' +
                  p.replace(/'/g, "\\'") + '\';document.getElementById(\'scSearch\').dispatchEvent(new Event(\'input\'));this.closest(\'#scNoResults\').style.display=\'none\'">' +
                  p + '</button>';
              }).join('')
            : '';
        }
      }
    }
  }

  /* ââ Filter button clicks ââ */
  document.querySelectorAll('.sc-filter-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      document.querySelectorAll('.sc-filter-btn').forEach(function (b) { b.classList.remove('active'); });
      this.classList.add('active');
      activeFilter = this.getAttribute('data-filter');
      applyFilters();
    });
  });

  /* ââ Back to top on scroll ââ */
  var backTop = document.getElementById('sc-back-top');
  window.addEventListener('scroll', function () {
    if (backTop) backTop.classList.toggle('show', window.scrollY > 400);
  }, { passive: true });

  /* ââ "/" shortcut to focus search ââ */
  document.addEventListener('keydown', function (e) {
    if (e.key === '/' && document.activeElement !== searchEl &&
        !['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)) {
      e.preventDefault();
      searchEl.focus();
    }
  });
});
</script>

</body>
</html>
